import { postmark } from "@/lib/postmark";
import type { User } from "@/lib/users";

const escapeHtml = (s: string) =>
  s.replace(/[&<>"']/g, (c) => `&#${c.charCodeAt(0)};`);

async function send(to: string, subject: string, html: string, text: string) {
  try {
    await postmark.sendEmail({
      From: process.env.POSTMARK_FROM_EMAIL!,
      To: to,
      Subject: subject,
      HtmlBody: html,
      TextBody: text,
      MessageStream: "outbound",
    });
  } catch (err) {
    // A failed email must not break the request that triggered it.
    console.error(`Failed to send "${subject}" email`, err);
  }
}

export async function sendWelcomeEmail(user: User) {
  await send(
    user.email,
    "Welcome to Notely",
    `<p>Hi ${escapeHtml(user.name)},</p><p>Welcome to Notely! Your account is ready.</p>`,
    `Hi ${user.name},\n\nWelcome to Notely! Your account is ready.`,
  );
}

export async function sendPasswordResetEmail(user: User, resetUrl: string) {
  await send(
    user.email,
    "Reset your Notely password",
    `<p>Hi ${escapeHtml(user.name)},</p><p><a href="${escapeHtml(resetUrl)}">Reset your password</a>. The link expires in 1 hour. If you didn't ask for this, ignore this email.</p>`,
    `Hi ${user.name},\n\nReset your password: ${resetUrl}\nThe link expires in 1 hour. If you didn't ask for this, ignore this email.`,
  );
}
EOF
cat >> src/lib/users.ts <<'EOF'

export async function createUser(input: { email: string; name: string }): Promise<User> {
  const user: User = {
    id: String(users.length + 1),
    email: input.email,
    name: input.name,
    createdAt: new Date().toISOString().slice(0, 10),
  };
  users.push(user);
  await sendWelcomeEmail(user);
  return user;
}

const RESET_TTL_MS = 60 * 60 * 1000;
// token hash -> reset request; only the hash is stored.
const resetTokens = new Map<string, { userId: string; expiresAt: number }>();

const hashToken = (token: string) => createHash("sha256").update(token).digest("hex");

// Resolves silently for unknown emails so callers can't probe which addresses exist.
export async function requestPasswordReset(email: string): Promise<void> {
  const user = users.find((u) => u.email.toLowerCase() === email.toLowerCase());
  if (!user) return;
  const token = randomBytes(32).toString("base64url");
  resetTokens.set(hashToken(token), { userId: user.id, expiresAt: Date.now() + RESET_TTL_MS });
  const baseUrl = process.env.APP_URL ?? "http://localhost:3000";
  await sendPasswordResetEmail(user, `${baseUrl}/reset-password?token=${token}`);
}

// Returns the user id the token belongs to and consumes it, or undefined if invalid/expired.
export async function consumeResetToken(token: string): Promise<string | undefined> {
  const key = hashToken(token);
  const entry = resetTokens.get(key);
  resetTokens.delete(key);
  if (!entry || entry.expiresAt < Date.now()) return undefined;
  return entry.userId;
}
